      en: "A bustling city in the Ayeyarwady Region, famous for its rice farming.",
      es: "Una ciudad bulliciosa en la región de Ayeyarwady, famosa por su cultivo de arroz.",
      pt: "Uma cidade movimentada na região de Ayeyarwady, famosa pelo seu cultivo de arroz.",
