      de: "Eine geschäftige Stadt am Irrawaddy-Fluss, die für den Handel mit Tabak und Baumwolle bekannt ist.",
      hu: "Nyüzsgő város az Irrawaddy folyón, amely dohány- és pamutkereskedelméről ismert.",
      ro: "Un oraș plin de viață pe râul Irrawaddy, cunoscut pentru comerțul cu tutun și bumbac.",
      en: "A bustling city on the Irrawaddy River, known for its trade in tobacco and cotton.",
      es: "Una bulliciosa ciudad a orillas del río Irawadi, conocida por el comercio de tabaco y algodón.",
      pt: "Uma cidade movimentada nas margens do rio Irrawaddy, conhecida pelo comércio de tabaco e algodão.",
